import Foundation

struct CurrencyFormatter {
    static func formatUSD(_ cents: Int) -> String {
        return "$\((cents / 100)).\((cents % 100))"
    }
}

let result = CurrencyFormatter.formatUSD(1999)
print("Price: \(result)")

import Foundation

protocol DataService {
    func count() -> Int
}

final class MockService: DataService {
    func count() -> Int {
        return 5
    }
}

final class CounterController {
    let service: DataService
    init(service: DataService) {
        self.service = service
    }
    func printCount() {
        print("Total: \(service.count())")
    }
}

let ctrl = CounterController(service: MockService())
ctrl.printCount()

