import Foundation

struct Account { 
    var balance: Double

    func canWithdraw(amount: Double) -> Bool {
        return amount > 0 && amount <= balance
    }
}

let acc = Account(balance: 100.0)
let ok = acc.canWithdraw(amount: 40.0)
print("Can withdraw: \(ok)")

import Foundation

struct TemperatureFormatter {
    static func toFahrenheit(celsius: Double) -> Double {
        return (celsius * 9.0 / 5.0) + 32.0
    }

    static func format(celsius: Double) -> String {
        let f = Int(toFahrenheit(celsius: celsius))
        return "\(f)°F"
    }
}

print(TemperatureFormatter.format(celsius: 20.0))

import Foundation

final class UserListDataSource {
    private(set) var users: [String] = []

    func add(name: String) {
        users.append(name)
    }

    func count() -> Int {
        return users.count
    }
}

let ds = UserListDataSource()
ds.add(name: "Taylor")
ds.add(name: "Jordan")
print("User count: \(ds.count())")
